export function getGuideBySlug(locale: string, slug: string): GuideArticle | undefined {
  const normalizedLocale = locale === "en" ? "en" : "es";
  return guideEntries.find((entry) => entry.slug[normalizedLocale] === slug)?.[normalizedLocale];
}

export function getGuideSlugs(locale: "es" | "en"): string[] {
  return guideEntries.map((entry) => entry.slug[locale]);
}

export function getGuideSitemapEntries() {
  return guideEntries.map(({ slug, lastModified }) => ({ slug, lastModified }));
}
